"""MPS dense ops: layernorm + fused MLP.

LayerNorm goes through the native Metal kernel
``_native.ops.layer_norm`` lifted from MLX's
``layer_norm_single_row``. The high-level ``layernorm_bias_into`` /
``layernorm_bias`` API matches the CUDA backend so kestrel can call
``_KERNELS.dense.layernorm_bias_into(...)`` arch-agnostically.

``fused_mlp_gelu_bias_residual_cuda_mps`` is still a torch composition —
the underlying matmul + gelu + add already dispatch to MPSGraph kernels
that are hard to beat without a custom matmul.
"""

import torch
import torch.nn.functional as F

# Side-effect import: loads the sidecar bridge, the pre-built Metal
# library, and exposes the direct native op surface.
from kestrel_kernels.mps import _native
from kestrel_kernels.swiglu.fallback import gated_activation_torch


def layernorm_bias_into(
    out: torch.Tensor,
    x: torch.Tensor,
    weight: torch.Tensor,
    bias: torch.Tensor,
    eps: float = 1e-5,
    *,
    variant: str = "auto",
) -> None:
    """LayerNorm forward via the Metal kernel.

    ``variant`` is accepted for signature parity with the CUDA backend
    (which has register-pressure variants); on MPS both map to the same
    kernel since the Metal kernel doesn't have the same ldg/stg knobs.
    """
    if x.ndim not in (2, 3):
        raise ValueError(f"x must be 2D or 3D, got {tuple(x.shape)}")
    if out.shape != x.shape:
        raise ValueError(f"out must match x shape {tuple(x.shape)}, got {tuple(out.shape)}")
    if weight.ndim != 1 or bias.ndim != 1:
        raise ValueError("weight and bias must be 1D")
    if x.shape[-1] != weight.shape[0] or weight.shape != bias.shape:
        raise ValueError("weight/bias must match x last dimension")

    if x.ndim == 3:
        b, t, n = x.shape
        x2 = x.reshape(b * t, n)
        # ``out.view(...)`` (not ``reshape``) so a non-contiguous output
        # raises rather than allocating a temporary that the kernel
        # writes to while the caller's tensor stays unchanged.
        out2 = out.view(b * t, n)
    else:
        x2 = x
        out2 = out

    # ``variant`` is accepted for signature parity with CUDA but ignored
    # at dispatch (Metal kernel has no register-pressure variants).
    if variant not in ("auto", "default", "reload_x"):
        raise ValueError(f"Unknown layernorm variant: {variant!r}")

    _native.ops.layer_norm(out2, x2, weight, bias, float(eps))


def layernorm_bias(
    x: torch.Tensor,
    weight: torch.Tensor,
    bias: torch.Tensor,
    *,
    eps: float = 1e-5,
) -> torch.Tensor:
    out = torch.empty_like(x)
    layernorm_bias_into(out, x, weight, bias, eps)
    return out


def _rmsnorm_torch_into(
    out: torch.Tensor,
    x: torch.Tensor,
    weight: torch.Tensor,
    eps: float,
) -> None:
    x_fp32 = x.float()
    out.copy_(
        F.rms_norm(
            x_fp32,
            weight.shape,
            weight.to(x_fp32.dtype),
            float(eps),
        ).to(x.dtype)
    )


def _supports_native_rmsnorm(
    out: torch.Tensor,
    x: torch.Tensor,
    weight: torch.Tensor,
) -> bool:
    if _native.ops is None:
        return False
    if x.ndim == 0 or x.shape[-1] == 0:
        return False
    if (
        x.device.type != "mps"
        or out.device.type != "mps"
        or weight.device.type != "mps"
        or x.dtype not in (torch.float16, torch.float32)
        or out.dtype != x.dtype
        or weight.dtype != torch.float32
        or not out.is_contiguous()
        or not weight.is_contiguous()
        or weight.shape != (x.shape[-1],)
        or x.shape[-1] % 4 != 0
        or x.shape[-1] > 4096
        or x.stride(-1) != 1
    ):
        return False
    if x.ndim == 1:
        return True
    row_stride = x.stride(-2)
    if row_stride <= 0:
        return False
    expected = row_stride * x.shape[-2]
    for dim in range(x.ndim - 3, -1, -1):
        if x.shape[dim] != 1 and x.stride(dim) != expected:
            return False
        expected *= x.shape[dim]
    return True


def rmsnorm_into(
    out: torch.Tensor,
    x: torch.Tensor,
    weight: torch.Tensor,
    eps: float = 1e-6,
) -> None:
    if x.ndim == 0:
        raise ValueError("x must have at least one dimension")
    if out.shape != x.shape:
        raise ValueError(f"out must match x shape {tuple(x.shape)}, got {tuple(out.shape)}")
    if weight.shape != (x.shape[-1],):
        raise ValueError(f"weight shape must be {(x.shape[-1],)}, got {tuple(weight.shape)}")
    if x.numel() == 0:
        return
    if _supports_native_rmsnorm(out, x, weight):
        _native.ops.rms_norm(out, x, weight, float(eps))
        return
    _rmsnorm_torch_into(out, x, weight, eps)


def rmsnorm(
    x: torch.Tensor,
    weight: torch.Tensor,
    eps: float = 1e-6,
) -> torch.Tensor:
    out = torch.empty_like(x, memory_format=torch.contiguous_format)
    rmsnorm_into(out, x, weight, eps)
    return out


def add_rmsnorm_into(
    out: torch.Tensor,
    residual: torch.Tensor,
    x: torch.Tensor,
    weight: torch.Tensor,
    eps: float = 1e-6,
) -> None:
    if residual.ndim == 0:
        raise ValueError("residual must have at least one dimension")
    if x.shape != residual.shape:
        raise ValueError(
            f"x must match residual shape {tuple(residual.shape)}, got {tuple(x.shape)}"
        )
    if out.shape != residual.shape:
        raise ValueError(
            f"out must match residual shape {tuple(residual.shape)}, got {tuple(out.shape)}"
        )
    if weight.shape != (residual.shape[-1],):
        raise ValueError(
            f"weight shape must be {(residual.shape[-1],)}, got {tuple(weight.shape)}"
        )
    if residual.numel() == 0:
        return
    if residual.numel() > 0 and out.data_ptr() == residual.data_ptr():
        raise ValueError("out must not alias residual")
    if (
        _supports_native_rmsnorm(out, x, weight)
        and residual.is_mps
        and residual.dtype == x.dtype
        and residual.is_contiguous()
    ):
        _native.ops.add_rms_norm(out, residual, x, weight, float(eps))
        return
    residual.add_(x)
    rmsnorm_into(out, residual, weight, eps)


def add_rmsnorm(
    residual: torch.Tensor,
    x: torch.Tensor,
    weight: torch.Tensor,
    eps: float = 1e-6,
) -> torch.Tensor:
    # Tried the native fused add-RMSNorm at Qwen [1, 2048]: it was 1.65x
    # faster standalone, but reduced the 64-token end-to-end result to
    # 16.8 tok/s from 17.4 tok/s; keep the end-to-end winner here.
    residual.add_(x)
    return F.rms_norm(residual.float(), weight.shape, weight, float(eps)).to(
        residual.dtype
    )


def gated_activation_into(
    out: torch.Tensor,
    gate_up: torch.Tensor,
    *,
    activation: str,
    layout: str,
) -> None:
    if (
        activation == "silu"
        and layout == "interleaved_i8"
        and _native.ops is not None
        and hasattr(_native.ops, "swiglu_interleaved_into")
        and gate_up.device.type == "mps"
        and out.device == gate_up.device
        and gate_up.dtype == torch.float16
        and out.dtype == torch.float16
        and gate_up.is_contiguous()
        and out.is_contiguous()
    ):
        _native.ops.swiglu_interleaved_into(out, gate_up)
        return
    gated_activation_torch(
        gate_up,
        activation=activation,
        layout=layout,
        out=out,
    )


def fused_mlp_gelu_bias_residual_cuda_mps(
    out: torch.Tensor,
    hidden: torch.Tensor,  # workspace; unused on MPS (torch handles allocation)
    x: torch.Tensor,
    w1: torch.Tensor,
    b1: torch.Tensor,
    w2: torch.Tensor,
    b2: torch.Tensor,
    residual: torch.Tensor,
    *,
    approximate: str = "tanh",
) -> None:
    """In-place ``out = residual + F.linear(F.gelu(F.linear(x, w1, b1)), w2, b2)``.

    ``hidden`` is a pre-allocated workspace the CUDA kernel writes the GELU'd
    intermediate into; PyTorch handles that allocation implicitly, so the
    argument is accepted for signature parity and not otherwise used.
    """
    h = F.gelu(F.linear(x, w1, b1), approximate=approximate)
    result = residual + F.linear(h, w2, b2)
    out.copy_(result)


def mlp_gelu_bias_residual_mps(
    x: torch.Tensor,
    w1: torch.Tensor,
    b1: torch.Tensor,
    w2: torch.Tensor,
    b2: torch.Tensor,
    residual: torch.Tensor,
    *,
    approximate: str = "tanh",
) -> torch.Tensor:
    """MPSGraph composition for the cross-backend high-level MLP API."""
    hidden = F.gelu(F.linear(x, w1, b1), approximate=approximate)
    return residual + F.linear(hidden, w2, b2)


__all__ = [
    "add_rmsnorm",
    "add_rmsnorm_into",
    "fused_mlp_gelu_bias_residual_cuda_mps",
    "mlp_gelu_bias_residual_mps",
    "layernorm_bias",
    "layernorm_bias_into",
    "rmsnorm",
    "rmsnorm_into",
    "gated_activation_into",
]
